/* Interactive financial preview. Never calls Stripe or changes actual visit settlements. */
function financeWallet(){extras.financePreview=extras.financePreview||{};const owner=state.role==='Owner HQ',key=owner?'owner:'+extras.location:'barber:'+activeBarberId();if(!extras.financePreview[key])extras.financePreview[key]={available:owner?284050:42050,pending:owner?41875:9600,tips:owner?28400:8600,week:owner?532000:128000,bank:'Chase •• 1100',instant:'Visa debit •• 4242',schedule:'daily',notify:true,payouts:[{id:'preview-1',amount:owner?124500:28500,fee:0,method:'standard',date:addDays(today,-1),status:'Paid',destination:'Chase •• 1100'},{id:'preview-2',amount:owner?82000:16000,fee:owner?1230:240,method:'instant',date:addDays(today,-3),status:'Paid',destination:'Visa debit •• 4242'},{id:'preview-3',amount:owner?96500:31000,fee:0,method:'standard',date:addDays(today,-5),status:'Paid',destination:'Chase •• 1100'}]};return extras.financePreview[key];}
function financeRow(p,index){return `<button class="finance-history-row" data-finance="receipt" data-index="${index}"><span class="finance-row-icon">${icon(p.method==='instant'?'lightning':'card')}</span><span class="details"><strong>${p.method==='instant'?'Instant payout':'Bank payout'}</strong><small>${pretty(p.date)} · ${esc(p.destination)}</small></span><span class="finance-row-total"><strong>${cents(p.amount-p.fee)}</strong><small class="finance-positive">${esc(p.status)}</small></span>${icon('chevron')}</button>`;}
function financeOverview(){const w=financeWallet();return `<section class="panel finance-hero"><div class="row between"><span class="finance-eyebrow">AVAILABLE TO PAY OUT</span><span class="finance-active"><span></span> Account active</span></div><strong class="finance-balance">${cents(w.available)}</strong><p>Your earnings, ready when you are.</p><div class="finance-actions"><button class="btn" data-finance="payout" data-method="instant" ${w.available<=0||!w.instant?'disabled':''}>${icon('lightning')} Get paid now ${icon('arrow')}</button><button class="btn secondary" data-finance="payout" data-method="standard" ${w.available<=0?'disabled':''}>Bank transfer</button></div><small>Instant to ${esc(w.instant||'Add a payout method')} · 1.5% instant payout fee</small></section><div class="finance-metrics">${[['clock','On the way',w.pending,'Clearing payments'],['chart','Paid this week',w.week,'Transferred this week'],['gift','Tips this week',w.tips,'Included in earnings']].map(([type,label,amount,sub])=>`<section class="panel"><span>${icon(type)} ${label}</span><strong>${cents(amount)}</strong><small>${sub}</small></section>`).join('')}</div><section class="panel finance-schedule"><span class="finance-row-icon">${icon('calendar')}</span><div><h3>${w.schedule==='manual'?'You control your payouts':w.schedule==='weekly'?'Next payout · Friday':'Next payout · Tomorrow'}</h3><p>${w.schedule==='manual'?'Transfer your available balance whenever you choose.':`Automatic ${w.schedule} payouts to ${esc(w.bank)}.`}</p></div><button class="text-btn" data-finance="tab" data-tab="settings">Manage ${icon('chevron')}</button></section><section class="panel finance-history"><div class="row between"><h2>Recent payouts</h2><button class="text-btn" data-finance="tab" data-tab="history">View all ${icon('arrow')}</button></div>${w.payouts.slice(0,3).map(financeRow).join('')}</section>`;}
function financeSettings(){const w=financeWallet();return `<section class="panel finance-settings"><h2>Payout destinations</h2><button class="finance-setting-row" data-finance="bank"><span class="finance-row-icon">${icon('card')}</span><span class="details"><strong>${esc(w.bank)}</strong><small>Bank account · standard payouts</small></span><span class="finance-active">Verified</span>${icon('chevron')}</button><button class="finance-setting-row" data-finance="bank"><span class="finance-row-icon">${icon('wallet')}</span><span class="details"><strong>${esc(w.instant)}</strong><small>Debit card · instant payouts</small></span><span class="finance-active">Ready</span>${icon('chevron')}</button></section><form class="panel finance-settings" id="finance-settings"><h2>Your payout preferences</h2><label class="field">Automatic payouts<select name="schedule"><option value="daily" ${w.schedule==='daily'?'selected':''}>Daily · every business day</option><option value="weekly" ${w.schedule==='weekly'?'selected':''}>Weekly · Friday</option><option value="manual" ${w.schedule==='manual'?'selected':''}>Manual · I’ll choose when</option></select></label><label class="finance-switch"><span><strong>Payout notifications</strong><small>A heads-up when money is on the way.</small></span><input type="checkbox" name="notify" role="switch" ${w.notify?'checked':''}></label><button class="btn">Save preferences</button><p id="finance-settings-saved" role="status"></p></form><section class="panel finance-settings"><div class="row between"><h2>Business details</h2><span class="finance-active">Verified</span></div><div class="line-item"><span>Account name</span><strong>${state.role==='Owner HQ'?'Hairflix':esc(activeStaff().name)}</strong></div><div class="line-item"><span>Business type</span><strong>${state.role==='Owner HQ'?'Barbershop & salon':'Independent professional'}</strong></div><div class="line-item"><span>Payments</span><strong class="finance-positive">Enabled</strong></div><div class="line-item"><span>Payouts</span><strong class="finance-positive">Enabled</strong></div></section>`;}
function financePayments(){return `<section class="panel finance-history"><div class="row between"><h2>Recent payments</h2><span class="finance-active">All settled</span></div>${[['John B.',3200,2000],['Alex Morgan',4000,1500],['Ryan Smith',4000,800],['Marcus Reed',3000,600]].map(([name,service,tip],i)=>`<div class="finance-payment-row">${clientPhoto(name)}<span class="details"><strong>${esc(name)}</strong><small>${pretty(addDays(today,-i))} · ${cents(service)} service + ${cents(tip)} tip</small></span><strong>${cents(service+tip)}</strong><span class="finance-paid">Paid</span></div>`).join('')}<p class="finance-fineprint"></p></section>`;}
function financePage(){const w=financeWallet(),tab=state.financeTab||'overview';return `${head(state.role==='Owner HQ'?'Your shop. Your earnings.':'Your work. Your earnings.','Payments, payouts and a little peace of mind.','')}<div class="finance-tabs" role="group" aria-label="Payment views">${[['overview','Overview'],['history','Payouts'],['payments','Payments'],['settings','Settings']].map(([id,label])=>`<button data-finance="tab" data-tab="${id}" class="${tab===id?'selected':''}" aria-pressed="${tab===id}">${label}</button>`).join('')}</div><div class="finance-page">${tab==='overview'?financeOverview():tab==='history'?`<section class="panel finance-history"><div class="row between"><h2>Payout history</h2><button class="btn small" data-finance="payout" data-method="instant" ${w.available<=0?'disabled':''}>${icon('plus')} New payout</button></div>${w.payouts.map(financeRow).join('')}</section>`:tab==='settings'?financeSettings():financePayments()}</div><p class="finance-preview-note"></p>`;}
function financeAmount(value){return /^\d+(\.\d{1,2})?$/.test(String(value))?Math.round(Number(value)*100):NaN;}
function financeQuote(amount,method){const fee=method==='instant'?Math.round(amount*.015):0;return {amount,fee,net:amount-fee};}
function financeDialog(html){const d=document.createElement('dialog');d.className='business-dialog finance-dialog';d.innerHTML=html;document.body.append(d);d.showModal();d.addEventListener('cancel',e=>{if(d.dataset.busy==='true')e.preventDefault();else d.remove();});d.addEventListener('click',e=>{if(e.target.closest('[data-finance-close]')&&d.dataset.busy!=='true'){d.close();d.remove();}});return d;}
function financePayout(method='instant'){const w=financeWallet(),d=financeDialog(`<div class="row between"><h2>Make it payday.</h2><button class="icon-btn" data-finance-close aria-label="Close">${icon('close')}</button></div><p class="muted">Available balance · ${cents(w.available)}</p><form id="finance-payout"><div class="finance-methods">${[['instant','Instant payout · 1.5%','Usually within minutes'],['standard','Bank transfer','1–2 business days']].map(([id,label,desc])=>`<label><input type="radio" name="method" value="${id}" ${id===method?'checked':''}><span><strong>${id==='instant'?icon('lightning'):''}${label}</strong><small>${desc}</small></span></label>`).join('')}</div><label class="field finance-amount">Amount to pay out ($)<input name="amount" type="number" inputmode="decimal" min="1" max="${(w.available/100).toFixed(2)}" step="0.01" value="${(w.available/100).toFixed(2)}" required></label><div id="finance-quote" aria-live="polite"></div><p class="connect-error" role="alert"></p><button class="btn full">Confirm payout ${icon('arrow')}</button><p class="finance-fineprint"></p></form>`);const form=d.querySelector('form');const quote=()=>{const f=new FormData(form),amount=financeAmount(f.get('amount')),method=f.get('method'),q=financeQuote(Number.isFinite(amount)?amount:0,method);d.querySelector('#finance-quote').innerHTML=`<div class="line-item"><span>Send to</span><strong>${esc(method==='instant'?w.instant:w.bank)}</strong></div><div class="line-item"><span>${method==='instant'?'Instant payout fee · 1.5%':'Bank transfer fee'}</span><strong>${cents(q.fee)}</strong></div><div class="line-item total"><span>You receive</span><strong>${cents(q.net)}</strong></div>`;};form.addEventListener('input',quote);quote();form.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(form),amount=financeAmount(f.get('amount')),method=f.get('method');if(!(method==='instant'?w.instant:w.bank)){form.querySelector('[role=alert]').textContent='Add a payout method in Settings first.';return;}if(!Number.isSafeInteger(amount)||amount<100||amount>w.available){form.querySelector('[role=alert]').textContent='Choose an amount between $1 and your available balance.';return;}if(d.dataset.busy==='true')return;d.dataset.busy='true';const submit=form.querySelector('.btn');submit.disabled=true;submit.innerHTML='<span class="ticket-spinner" aria-hidden="true"></span> Sending payout…';await new Promise(resolve=>setTimeout(resolve,650));const q=financeQuote(amount,method),p={id:'preview-'+crypto.randomUUID(),amount,fee:q.fee,method,date:today,status:method==='instant'?'Paid':'On the way',destination:method==='instant'?w.instant:w.bank};w.available-=amount;w.payouts.unshift(p);save();d.dataset.busy='false';d.innerHTML=`<div class="finance-success-mark">${icon('check')}</div><h2>${method==='instant'?'Payout sent.':'Your payout is on its way.'}</h2><strong class="finance-success-amount">${cents(q.net)}</strong><p>${esc(p.destination)}</p><p class="muted">${method==='instant'?'Expected within minutes.':'Expected in 1–2 business days.'}</p><p class="finance-fineprint"></p><button class="btn full" data-finance-close>Done</button>`;render();});}
function financeBankDialog(){const w=financeWallet(),d=financeDialog(`<div class="row between"><h2>Your payout accounts.</h2><button class="icon-btn" data-finance-close aria-label="Close">${icon('close')}</button></div><p class="muted">Choose a sample destination to explore the settings.</p><form id="finance-bank"><label class="field">Bank account<select name="bank"><option ${w.bank==='Chase •• 1100'?'selected':''}>Chase •• 1100</option><option ${w.bank==='Wells Fargo •• 6789'?'selected':''}>Wells Fargo •• 6789</option></select></label><label class="field">Instant payout card<select name="instant"><option ${w.instant==='Visa debit •• 4242'?'selected':''}>Visa debit •• 4242</option><option ${w.instant==='Mastercard debit •• 5556'?'selected':''}>Mastercard debit •• 5556</option></select></label><button class="btn full">Save destinations</button><p class="finance-fineprint">Sample accounts only. No bank or card information is collected.</p></form>`);d.querySelector('form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);w.bank=String(f.get('bank'));w.instant=String(f.get('instant'));save();d.close();d.remove();render();toast('Payout destinations updated.');});}
const connectExtraBefore=renderExtraView;
renderExtraView=function(v){if(['hConnect','pConnect','hPayouts','pPayout','earnings'].includes(v)&&isStaff())return financePage();return connectExtraBefore(v);};
const renderBeforeConnect=render;render=function(){renderBeforeConnect();if(!isStaff()||state.view!=='more')return;const page=state.role==='Owner HQ'?'hConnect':'pConnect';document.querySelector('main')?.insertAdjacentHTML('afterbegin',`<button class="barber-availability connect-shortcut" data-view="${page}">${icon('wallet')}<span><strong>Payments & payouts</strong><small>Your earnings, payout accounts and preferences.</small></span>${icon('chevron')}</button>`);};
document.addEventListener('click',e=>{const button=e.target.closest('[data-finance]');if(!button||!isStaff())return;const d=button.dataset;if(d.finance==='tab'){state.financeTab=d.tab;render();}if(d.finance==='payout')financePayout(d.method);if(d.finance==='bank')financeBankDialog();if(d.finance==='receipt'){const p=financeWallet().payouts[Number(d.index)];if(!p)return;financeDialog(`<h2>${p.method==='instant'?icon('lightning')+' Instant payout':'Bank payout'}</h2><p>${pretty(p.date)} · ${esc(p.status)}</p><div class="line-item"><span>Amount</span><strong>${cents(p.amount)}</strong></div><div class="line-item"><span>Fee</span><strong>${cents(p.fee)}</strong></div><div class="line-item total"><span>Received / arriving</span><strong>${cents(p.amount-p.fee)}</strong></div><p>${esc(p.destination)}</p><p class="finance-fineprint"></p><button class="btn full" data-finance-close>Done</button>`);}});
document.addEventListener('submit',e=>{if(e.target.id!=='finance-settings'||!isStaff())return;e.preventDefault();const f=new FormData(e.target),w=financeWallet();w.schedule=String(f.get('schedule'));w.notify=f.has('notify');save();document.querySelector('#finance-settings-saved').textContent='Preferences saved.';});
render();
